using System.Data;
using Essco.Application.HumanResources;
using Microsoft.Data.SqlClient;
namespace Essco.Infrastructure.Data;

public sealed class SqlServerEmployeeMovementRepository(string connectionString, int timeout) : IEmployeeMovementRepository
{
    public ValueTask<int> SaveVacationAsync(VacationInput x, CancellationToken t) => Insert("Empleado_Vacaciones", "[Cedula_Empleado],[FechaIni],[FechaFin],[Dias],[Comentario],[FechaCrea],[Estado]", "@Employee,@From,@To,@Days,@Detail,SYSDATETIME(),0", x.EmployeeId, x.From, x.To, x.Days, x.Comments, "", "", t); public ValueTask<int> SaveDisabilityAsync(DisabilityInput x, CancellationToken t) => Insert("Empleado_Incapacidades", "[Cedula_Empleado],[FechaInicio],[FechaFin],[DiasIncapacidad],[NumBoleta],[Detalle],[Tipo],[FechaCrea],[Estado]", "@Employee,@From,@To,@Days,@Voucher,@Detail,@Type,SYSDATETIME(),0", x.EmployeeId, x.From, x.To, x.Days, x.Detail, x.Type, x.Voucher, t); public ValueTask<int> SaveDeductionAsync(DeductionInput x, CancellationToken t) => InsertDeduction(x, t); public ValueTask<int> SaveLoanAsync(LoanInput x, CancellationToken t) => InsertLoan(x, t);
    public async ValueTask<bool> AnnulAsync(string type, int number, CancellationToken t) { var table = type switch { "vacation" => "Empleado_Vacaciones", "disability" => "Empleado_Incapacidades", "deduction" => "Empleado_Deducciones", "loan" => "Empleado_ValesPrestamos", _ => null }; if (table is null) return false; await using var c = await Open(t); await using var cmd = Cmd($"UPDATE [dbo].[{table}] SET [Estado]=1 WHERE [Consecutivo]=@Number AND ISNULL([Estado],0)=0", c); cmd.Parameters.Add("@Number", SqlDbType.Int).Value = number; return await cmd.ExecuteNonQueryAsync(t) == 1; }
    private async ValueTask<int> Insert(string table, string columns, string values, string employee, DateOnly from, DateOnly to, decimal days, string detail, string type, string voucher, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd($"INSERT INTO [dbo].[{table}]({columns}) OUTPUT INSERTED.[Consecutivo] VALUES({values})", c); P(cmd, "@Employee", 100, employee); cmd.Parameters.Add("@From", SqlDbType.Date).Value = from.ToDateTime(TimeOnly.MinValue); cmd.Parameters.Add("@To", SqlDbType.Date).Value = to.ToDateTime(TimeOnly.MinValue); Dec(cmd, "@Days", days); P(cmd, "@Detail", 1000, detail); P(cmd, "@Type", 100, type); P(cmd, "@Voucher", 100, voucher); return Convert.ToInt32(await cmd.ExecuteScalarAsync(t)); }
    private async ValueTask<int> InsertDeduction(DeductionInput x, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd("INSERT INTO [dbo].[Empleado_Deducciones]([Cedula_Empleado],[Categoria],[Monto],[Detalle],[Fecha],[Estado],[PorcentajePrimerQuincena],[PorcentajeSegundaQuincena]) OUTPUT INSERTED.[Consecutivo] VALUES(@Employee,@Type,@Amount,@Detail,@Date,0,@First,@Second)", c); P(cmd, "@Employee", 100, x.EmployeeId); P(cmd, "@Type", 100, x.Category); Dec(cmd, "@Amount", x.Amount); P(cmd, "@Detail", 1000, x.Detail); cmd.Parameters.Add("@Date", SqlDbType.Date).Value = x.Date.ToDateTime(TimeOnly.MinValue); cmd.Parameters.Add("@First", SqlDbType.Int).Value = x.FirstPercentage; cmd.Parameters.Add("@Second", SqlDbType.Int).Value = x.SecondPercentage; return Convert.ToInt32(await cmd.ExecuteScalarAsync(t)); }
    private async ValueTask<int> InsertLoan(LoanInput x, CancellationToken t) { await using var c = await Open(t); await using var cmd = Cmd("INSERT INTO [dbo].[Empleado_ValesPrestamos]([CedulaEmpleado],[NombreEmpleado],[FechaCrea],[Monto],[Saldo],[Tipo],[Detalle],[MontoAbonoQuincenal],[Estado]) OUTPUT INSERTED.[Consecutivo] VALUES(@Employee,@Name,@Date,@Amount,@Amount,@Type,@Detail,@Payment,0)", c); P(cmd, "@Employee", 100, x.EmployeeId); P(cmd, "@Name", 300, x.EmployeeName); cmd.Parameters.Add("@Date", SqlDbType.Date).Value = x.Date.ToDateTime(TimeOnly.MinValue); Dec(cmd, "@Amount", x.Amount); Dec(cmd, "@Payment", x.FortnightPayment); P(cmd, "@Type", 100, x.Type); P(cmd, "@Detail", 1000, x.Detail); return Convert.ToInt32(await cmd.ExecuteScalarAsync(t)); }
    private async ValueTask<SqlConnection> Open(CancellationToken t) { var c = new SqlConnection(connectionString); await c.OpenAsync(t); return c; }
    private SqlCommand Cmd(string s, SqlConnection c) => new(s, c) { CommandTimeout = timeout }; private static void P(SqlCommand c, string n, int z, string? v) => c.Parameters.Add(n, SqlDbType.NVarChar, z).Value = v?.Trim() ?? ""; private static void Dec(SqlCommand c, string n, decimal v) { var p = c.Parameters.Add(n, SqlDbType.Decimal); p.Precision = 19; p.Scale = 4; p.Value = v; }
}
